int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *ohead = &sbi->s_orphan;
    struct ext4_orphan *op;
    int err = 0;

    spin_lock(&ohead->o_lock);
    if (!ei->i_orphan) {
        spin_unlock(&ohead->o_lock);
        return 0;
    }

    list_for_each_entry(op, &ohead->o_list, o_list) {
        if (op->ino == inode->i_ino) {
            list_del_init(&op->o_list);
            ei->i_orphan = 0;
            break;
        }
    }
    spin_unlock(&ohead->o_lock);

    if (handle) {
        err = ext4_mark_inode_dirty(handle, inode);
        if (err)
            return err;
    }

    return 0;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_iloc iloc;
    struct ext4_super_block *es;
    struct ext4_group_desc *gdp;
    struct buffer_head *bh;
    int ret = 0;
    int err;

    if (EXT4_SB(inode->i_sb)->s_journal == NULL ||
        EXT4_SB(inode->i_sb)->s_mount_state & EXT4_ORPHAN_FS)
        return 0;

    spin_lock(&EXT4_I(inode->i_sb->s_root)->i_orphan_lock);
    if (!list_empty(&ei->i_orphan)) {
        list_del_init(&ei->i_orphan);
    } else {
        spin_unlock(&EXT4_I(inode->i_sb->s_root)->i_orphan_lock);
        return 0;
    }
    spin_unlock(&EXT4_I(inode->i_sb->s_root)->i_orphan_lock);

    if (!handle)
        return 0;

    ret = ext4_reserve_inode_defrag(inode, 0);
    if (ret < 0)
        return ret;

    err = ext4_get_inode_loc(inode, &iloc);
    if (err) {
        ext4_std_error(inode->i_sb, err);
        return err;
    }

    bh = iloc.bh;
    gdp = ext4_get_group_desc(inode->i_sb, EXT4_INO(inode) - 1, NULL);
    if (!gdp) {
        ret = -EINVAL;
        goto out;
    }

    es = EXT4_SB(inode->i_sb)->s_es;
    if (es->s_last_orphan == cpu_to_cpu32(EXT4_INO(inode))) {
        ext4_lock_and_clean(bh);
        es->s_last_orphan = 0;
        ext4_mark_super_dirty(inode->i_sb);
    }

out:
    brelse(bh);
    return ret;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *o;
    int err = 0;

    if (!ext4_journal_available(inode->i_sb))
        return -EINVAL;

    if (inode->i_nlink == 0)
        return -ENOENT;

    mutex_lock(&sbi->s_orphan_lock);
    if (list_empty(&ei->i_orphan)) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -ENOENT;
    }

    list_del_init(&ei->i_orphan);

    if (handle) {
        err = ext4_handle_dirty_metadata(handle, inode, ei->i_bh);
        if (err) {
            mutex_unlock(&sbi->s_orphan_lock);
            return err;
        }
    }

    mutex_unlock(&sbi->s_orphan_lock);

    return 0;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan_list *orphan;
    int ret = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb) || !sbi->s_mount_state)
        return 0;

    down_write(&sbi->s_orphan_lock);
    list_for_each_entry(orphan, &sbi->s_orphan, list) {
        if (orphan->ino == inode->i_ino) {
            list_del(&orphan->list);
            kmem_cache_free(GFP_NOFS, orphan);
            break;
        }
    }

    up_write(&sbi->s_orphan_lock);

    if (handle) {
        ext4_journal_stop(handle);
    }

    return ret;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *o;
    int ret = 0;

    if (!ext4_journal_has_feature_data_journalling(inode->i_sb))
        return 0;

    spin_lock(&sbi->s_orphan_lock);
    list_for_each_entry(o, &sbi->s_orphan, list) {
        if (o->inum == inode->i_ino) {
            list_del(&o->list);
            kfree(o);
            break;
        }
    }
    spin_unlock(&sbi->s_orphan_lock);

    if (handle) {
        ret = ext4_handle_dirty_metadata(handle, NULL, inode);
        if (ret < 0)
            return ret;
    }

    return ret;
}
